// Agent 122 Payload Processor
const item = $json.body || $json;
const correlationId = item.correlationId || `trace_122_${Date.now()}`;
const payloadData = item.data || item;

return {
  json: {
    agentId: '122',
    agentName: 'dbt Data Model Test & Docs Bot',
    correlationId,
    payloadData,
    receivedAt: new Date().toISOString()
  }
};

// Format execution output
const raw = $json.output || $json.text || '';
let parsed = {};
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
} catch (e) {
  parsed = { rawOutput: raw };
}

const orig = $('Parse & Enrich Context').item.json;
return {
  json: {
    agentId: orig.agentId,
    agentName: orig.agentName,
    correlationId: orig.correlationId,
    status: parsed.status || 'SUCCESS',
    summary: parsed.summary || 'Task completed autonomously.',
    action_items: parsed.action_items || [],
    metrics: parsed.metrics || {},
    completedAt: new Date().toISOString()
  }
};
